CREATE TABLE "Servicios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" text NOT NULL,
    "DuracionMin" integer NOT NULL,
    "Precio" numeric NOT NULL,
    CONSTRAINT "PK_Servicios" PRIMARY KEY ("Id")
);


CREATE TABLE "Usuarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Usuario" text NOT NULL,
    "PasswordHash" text NOT NULL,
    "Nombre" text NOT NULL,
    "Rol" text NOT NULL,
    "Telefono" text NOT NULL,
    CONSTRAINT "PK_Usuarios" PRIMARY KEY ("Id")
);


CREATE TABLE "Barberos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UsuarioId" integer,
    "Nombre" text NOT NULL,
    "FotoUrl" text,
    CONSTRAINT "PK_Barberos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Barberos_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id")
);


CREATE TABLE "BarberoServicios" (
    "BarberoId" integer NOT NULL,
    "ServicioId" integer NOT NULL,
    CONSTRAINT "PK_BarberoServicios" PRIMARY KEY ("BarberoId", "ServicioId"),
    CONSTRAINT "FK_BarberoServicios_Barberos_BarberoId" FOREIGN KEY ("BarberoId") REFERENCES "Barberos" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_BarberoServicios_Servicios_ServicioId" FOREIGN KEY ("ServicioId") REFERENCES "Servicios" ("Id") ON DELETE CASCADE
);


CREATE TABLE "Citas" (
    "Id" uuid NOT NULL,
    "ClienteId" integer NOT NULL,
    "BarberoId" integer NOT NULL,
    "ServicioId" integer NOT NULL,
    "InicioUtc" timestamp with time zone NOT NULL,
    "FinUtc" timestamp with time zone NOT NULL,
    "Estado" text NOT NULL,
    "MotivoRechazo" text,
    CONSTRAINT "PK_Citas" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Citas_Barberos_BarberoId" FOREIGN KEY ("BarberoId") REFERENCES "Barberos" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Citas_Servicios_ServicioId" FOREIGN KEY ("ServicioId") REFERENCES "Servicios" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Citas_Usuarios_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES "Usuarios" ("Id") ON DELETE CASCADE
);


CREATE TABLE "CitaBloques" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BarberoId" integer NOT NULL,
    "BloqueInicioUtc" timestamp with time zone NOT NULL,
    "CitaId" uuid NOT NULL,
    CONSTRAINT "PK_CitaBloques" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CitaBloques_Citas_CitaId" FOREIGN KEY ("CitaId") REFERENCES "Citas" ("Id") ON DELETE CASCADE
);


