CREATE INDEX "IX_Barberos_UsuarioId" ON "Barberos" ("UsuarioId");


CREATE INDEX "IX_BarberoServicios_ServicioId" ON "BarberoServicios" ("ServicioId");


CREATE UNIQUE INDEX "IX_CitaBloques_BarberoId_BloqueInicioUtc" ON "CitaBloques" ("BarberoId", "BloqueInicioUtc");


CREATE INDEX "IX_CitaBloques_CitaId" ON "CitaBloques" ("CitaId");


CREATE INDEX "IX_Citas_BarberoId_InicioUtc" ON "Citas" ("BarberoId", "InicioUtc");


CREATE INDEX "IX_Citas_ClienteId" ON "Citas" ("ClienteId");


CREATE INDEX "IX_Citas_ServicioId" ON "Citas" ("ServicioId");


CREATE UNIQUE INDEX "IX_Usuarios_Usuario" ON "Usuarios" ("Usuario");


SELECT setval(
    pg_get_serial_sequence('"Servicios"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Servicios") + 1,
        nextval(pg_get_serial_sequence('"Servicios"', 'Id'))),
    false);
SELECT setval(
    pg_get_serial_sequence('"Usuarios"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Usuarios") + 1,
        nextval(pg_get_serial_sequence('"Usuarios"', 'Id'))),
    false);
SELECT setval(
    pg_get_serial_sequence('"Barberos"', 'Id'),
    GREATEST(
